CREATE TABLE `premiacoes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `participante_id` int NOT NULL,
  `categoria_id` int NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDENTE',
  `data_entrega` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `status_entrega` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'NAO',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_premiacao` (`participante_id`,`categoria_id`),
  KEY `fk_premiacoes_categoria` (`categoria_id`),
  CONSTRAINT `fk_premiacoes_categoria` FOREIGN KEY (`categoria_id`) REFERENCES `categorias` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_premiacoes_participante` FOREIGN KEY (`participante_id`) REFERENCES `participantes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `premiacoes_ibfk_1` FOREIGN KEY (`participante_id`) REFERENCES `participantes` (`id`),
  CONSTRAINT `premiacoes_ibfk_2` FOREIGN KEY (`categoria_id`) REFERENCES `categorias` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
